// usage: node measure.js <scratchpad> <subdir> ; prints JSON {board: [[dataC, h, w, text, insideImport]]}
const { chromium } = require('playwright-core'); const fs = require('fs');
const S = process.argv[2], sub = process.argv[3];
const boards = JSON.parse(fs.readFileSync(`${S}/boards/new/project/canvas.json`, 'utf8')).boards;
(async () => {
  const b = await chromium.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome' }); const out = {};
  for (const [name, bb] of Object.entries(boards)) {
    const p = await b.newPage({ viewport: { width: bb.w, height: Math.max(bb.h, 240) } });
    try {
      await p.goto(`http://127.0.0.1:8772/${sub}/${name}`, { waitUntil: 'networkidle' }); await p.evaluate(() => document.fonts.ready); await p.waitForTimeout(500);
      out[name] = await p.evaluate(() => {
        const res = [];
        const walk = (root) => { for (const el of root.querySelectorAll('*')) { if (el.shadowRoot) walk(el.shadowRoot); } 
          for (const el of root.querySelectorAll('[data-c^="Button/"]')) { const r = el.getBoundingClientRect();
            res.push([el.getAttribute('data-c'), Math.round(r.height * 10) / 10, Math.round(r.width), (el.textContent || '').trim().slice(0, 30), !!el.closest('dc-import') || root !== document]); } };
        walk(document); return res; });
    } catch (e) { out[name] = 'FAILED ' + e.message.split('\n')[0]; }
    await p.close();
  }
  await b.close(); fs.writeFileSync(`${S}/measure-${sub}.json`, JSON.stringify(out));
})();
