// usage: node shots.js <list.json> ; list = [{url, out, w, h}]
const { chromium } = require('playwright-core'); const fs = require('fs');
(async () => {
  const list = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  const b = await chromium.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome' }); const errs = {};
  for (const it of list) {
    if (fs.existsSync(it.out)) continue;
    try {
    const p = await b.newPage({ viewport: { width: it.w, height: it.h }, deviceScaleFactor: 1 });
    p.on('pageerror', e => { (errs[it.out] ||= []).push(e.message); });
    p.on('console', m => { if (m.type() === 'error') (errs[it.out] ||= []).push(m.text()); });
    await p.goto(it.url, { waitUntil: 'networkidle' }); await p.evaluate(() => document.fonts.ready); await p.waitForTimeout(700);
    await p.screenshot({ path: it.out, fullPage: true, timeout: 120000 }); await p.close();
    } catch (e) { (errs[it.out] ||= []).push('FAILED ' + e.message.split('\n')[0]); }
  }
  await b.close(); console.log(JSON.stringify(errs));
})();
# usage: compare_fixed.py <scratchpad>; new vs fixed per board, writes DIFFfix pngs
import sys, json, numpy as np
from PIL import Image
S = sys.argv[1]; D = f"{S}/shots"
def load(f): return np.asarray(Image.open(f).convert("RGB")).astype(int)
new = json.load(open(f"{S}/boards/new/project/canvas.json"))["boards"]; same = 0; out = []
for b in new:
    if b == "comp-agent-row-tool.dc.html": continue
    A, B = load(f"{D}/new--{b}.png"), load(f"{D}/fixed--{b}.png")
    if A.shape != B.shape: out.append(f"  SIZE {b}: {A.shape[:2]} -> {B.shape[:2]}"); continue
    d = np.abs(A - B).max(axis=2) > 8; n = int(d.sum())
    if not n: same += 1; continue
    ys, xs = np.nonzero(d); img = (A * 0.3).astype(np.uint8); img[d] = [255, 0, 0]; Image.fromarray(img).save(f"{D}/DIFFfix--{b}.png")
    out.append(f"  {b}: {n} px in x {xs.min()}-{xs.max()}, y {ys.min()}-{ys.max()}")
print(f"identical: {same}; changed: {len(out)}"); print("\n".join(out))
