.history-action:hover:enabled { background: var(--surface-subtle); }
.history-action:disabled { opacity: 0.5; }

/* A failed print is the one inverse card: every role takes its on-failure
   counterpart. */
.history-card.print-failed {
  background: var(--surface-failure-inverse);
  box-shadow: none;
  color: var(--text-on-failure-primary);
}

.print-failed .history-kind { color: var(--status-danger-on-inverse); }
